DROP TABLE IF EXISTS `teaching_journals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `teaching_journals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `school_id` bigint unsigned NOT NULL,
  `schedule_id` bigint unsigned NOT NULL,
  `teacher_id` bigint unsigned NOT NULL,
  `attendance_id` bigint unsigned DEFAULT NULL,
  `journal_date` date NOT NULL,
  `topic` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `learning_objectives` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `teaching_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `reflection` text COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT (now()),
  `updated_at` timestamp NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  UNIQUE KEY `uq_schedule_journal_date` (`schedule_id`,`journal_date`),
  KEY `teaching_journals_school_id_schools_id_fk` (`school_id`),
  KEY `teaching_journals_teacher_id_teachers_id_fk` (`teacher_id`),
  KEY `teaching_journals_attendance_id_attendances_id_fk` (`attendance_id`),
  CONSTRAINT `teaching_journals_attendance_id_attendances_id_fk` FOREIGN KEY (`attendance_id`) REFERENCES `attendances` (`id`) ON DELETE SET NULL,
  CONSTRAINT `teaching_journals_schedule_id_schedules_id_fk` FOREIGN KEY (`schedule_id`) REFERENCES `schedules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `teaching_journals_school_id_schools_id_fk` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE CASCADE,
  CONSTRAINT `teaching_journals_teacher_id_teachers_id_fk` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

